import React, { useState } from 'react';
import { useGoogleLogin } from '@react-oauth/google';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import useAuthStore from '../../store/authStore';
import api from '../../api/axios';

const GoogleLoginButton = ({ label = 'Continue with Google' }) => {
  const { setAuth } = useAuthStore();
  const navigate    = useNavigate();
  const [loading,   setLoading] = useState(false);

  const login = useGoogleLogin({
    onSuccess: async (tokenResponse) => {
      if (loading) return;
      setLoading(true);
      try {
        const userInfo = await fetch(
          'https://www.googleapis.com/oauth2/v3/userinfo',
          { headers: { Authorization: `Bearer ${tokenResponse.access_token}` } }
        );
        const userData = await userInfo.json();

        const res = await api.post('/auth/google/', {
          token: tokenResponse.access_token,
          email: userData.email,
          name:  userData.name,
        });

        setAuth(res.data.user, res.data.access, res.data.refresh);
        toast.success(`Welcome, ${res.data.user.full_name || res.data.user.username}`);
        navigate('/');
      } catch (err) {
        toast.error(err.response?.data?.error || 'Google login failed. Try again.');
      } finally {
        setLoading(false);
      }
    },
    onError: () => {
      toast.error('Google login cancelled.');
      setLoading(false);
    },
    flow: 'implicit',
  });

  return (
    <button
      type="button"
      onClick={() => { if (!loading) login(); }}
      disabled={loading}
      className="w-full flex items-center justify-center gap-3 py-3 px-4
                 border-2 border-gray-200 dark:border-gray-700 rounded-xl
                 hover:bg-gray-50 dark:hover:bg-gray-800 transition
                 disabled:opacity-60 disabled:cursor-not-allowed bg-white
                 dark:bg-gray-900">
      {loading ? (
        <div className="w-5 h-5 border-2 border-gray-300 border-t-primary
                        rounded-full animate-spin" />
      ) : (
        <svg width="20" height="20" viewBox="0 0 24 24">
          <path fill="#4285F4"
            d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04
               2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
          <path fill="#34A853"
            d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23
               1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99
               20.53 7.7 23 12 23z"/>
          <path fill="#FBBC05"
            d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43
               8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/>
          <path fill="#EA4335"
            d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97
               1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6
               3.3-4.53 6.16-4.53z"/>
        </svg>
      )}
      <span className="text-sm font-semibold text-gray-700 dark:text-gray-300">
        {loading ? 'Signing in...' : label}
      </span>
    </button>
  );
};

export default GoogleLoginButton;
